     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/estimate_learning_run_api_v1_knowledge_base_learning_runs_estimate_post
     */
    public function estimateLearningRun(
        string $scopeMode,
        ?int $lastN = null,
        ?string $sinceDate = null,
        ?array $channelIds = null,
        ?string $kbFolderId = null,
        ?string $idempotencyKey = null,
    ): void {
        $this->connector->send(new Request(
            Method::Post,
            '/knowledge-base/learning-runs/estimate',
            body: Payload::body([
                'scope_mode' => $scopeMode,
                'last_n' => $lastN,
                'since_date' => $sinceDate,
                'channel_ids' => $channelIds,
                'kb_folder_id' => $kbFolderId,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

    /**
     * Get Learning Run.
     *
     * One learning run with its progress counters. Poll this while it runs.
     *
     * Scopes: knowledge_base:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/get_learning_run_api_v1_knowledge_base_learning_runs__run_id__get
     */
    public function getLearningRun(string $runId): void
    {
        $this->connector->send(new Request(
            Method::Get,
            '/knowledge-base/learning-runs/'.Payload::segment($runId),
        ));
    }

    /**
     * Cancel Learning Run.
     *
     * Cancel a learning run. A queued run stops at once; a running run stops after the conversation it
     * is working on. Entries already created stay in review. Cancelling a finished run changes
     * nothing.
     *
     * Workspace owners and admins only: anyone else gets 403 learning_run_owner_admin_only.
     *
     * Scopes: knowledge_base:manage.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/cancel_learning_run_api_v1_knowledge_base_learning_runs__run_id__cancel_post
     */
    public function cancelLearningRun(string $runId, ?string $idempotencyKey = null): void
    {
        $this->connector->send(new Request(
            Method::Post,
            '/knowledge-base/learning-runs/'.Payload::segment($runId).'/cancel',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

    /**
     * List Managed Faqs.
     *
     * List all managed FAQ documents, optionally filtered by folder.
     *
     * Scopes: knowledge_base:read.
     *
     * @param  ?string  $folderId  Filter by folder ID
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/list_managed_faqs_api_v1_knowledge_base_managed_faqs_get
     */
    public function listManaged(?string $folderId = null): ManagedFaqList
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/knowledge-base/managed-faqs',
            query: Payload::query(['folder_id' => $folderId]),
        ));

        return ManagedFaqList::fromArray($response->data());
    }

    /**
     * Create Managed Faq.
     *
     * Create a new managed FAQ document.
     *
     * Folder validation: - Cannot create FAQs in system folders 'websites' or 'ticket-summaries' - If
     * no folder_id is provided, auto-assigns to the 'General' system folder
     *
     * Scopes: knowledge_base:create.
     *
     * @param  string  $title  Document title
     * @param  ?string  $folderId  Parent folder ID (null for root level)
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/create_managed_faq_api_v1_knowledge_base_managed_faqs_post
     */
    public function createManaged(string $title, ?string $folderId = null, ?string $idempotencyKey = null): ManagedFaq
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/knowledge-base/managed-faqs',
            body: Payload::body(['title' => $title, 'folder_id' => $folderId]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return ManagedFaq::fromArray($response->data());
    }

    /**
     * Delete Managed Faq.
     *
     * Delete a managed FAQ document and all its items.
     *
     * Scopes: knowledge_base:delete.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/delete_managed_faq_api_v1_knowledge_base_managed_faqs__document_id__delete
     */
    public function deleteManaged(string $documentId): FaqOperation
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/knowledge-base/managed-faqs/'.Payload::segment($documentId),
        ));

        return FaqOperation::fromArray($response->data());
    }

    /**
     * Get Managed Faq.
     *
     * Get a managed FAQ document with all its Q&A items.
     *
     * Scopes: knowledge_base:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/get_managed_faq_api_v1_knowledge_base_managed_faqs__document_id__get
     */
    public function getManaged(string $documentId): ManagedFaqDetail
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/knowledge-base/managed-faqs/'.Payload::segment($documentId),
        ));

        return ManagedFaqDetail::fromArray($response->data());
    }

    /**
     * Update Managed Faq.
     *
     * Update a managed FAQ document title.
     *
     * Scopes: knowledge_base:update.
     *
     * @param  ?string  $title  Document title
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/update_managed_faq_api_v1_knowledge_base_managed_faqs__document_id__put
     */
    public function updateManaged(string $documentId, ?string $title = null): ManagedFaq
    {
        $response = $this->connector->send(new Request(
            Method::Put,
            '/knowledge-base/managed-faqs/'.Payload::segment($documentId),
            body: Payload::body(['title' => $title]),
        ));

        return ManagedFaq::fromArray($response->data());
    }

    /**
     * Sync Managed Faq.
     *
     * Sync a managed FAQ document to Gemini RAG.
     *
     * This compiles all Q&A items and uploads them to Gemini.
     *
     * Scopes: knowledge_base:update.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/FAQ%20Management/sync_managed_faq_api_v1_knowledge_base_managed_faqs__document_id__sync_post
     */
    public function syncManaged(string $documentId, ?string $idempotencyKey = null): FaqSync
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/knowledge-base/managed-faqs/'.Payload::segment($documentId).'/sync',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return FaqSync::fromArray($response->data());
    }
}
